def _inversion_count(perm) -> int:
    count = 0
    for i in range(len(perm)):
        for j in range(i + 1, len(perm)):
            if perm[i] > perm[j]:
                count += 1
    return count


def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    best = None

    for row_perm in permutations(range(H)):
        for col_perm in permutations(range(W)):
            if all(
                B[i][j] == A[row_perm[i]][col_perm[j]]
                for i in range(H)
                for j in range(W)
            ):
                operations = _inversion_count(row_perm) + _inversion_count(col_perm)
                if best is None or operations < best:
                    best = operations

    return best if best is not None else 0
