        for mask, cur in enumerate(dp):
            if cur < 1:
                continue
            for r in rows_with_value[v]:
                bit = bits[r]
                if mask & bit:
                    continue
                nmask = mask | bit
                cand = cur + v
                if cand > ndp[nmask]:
                    ndp[nmask] = cand
        dp = ndp

    return max(dp)
