# solution.py
from collections import defaultdict


# Optimized solution using digit DP and memoization

def count_beautiful_numbers(l: int, r: int) -> int:
    if l > r:
        return 0
    dp = defaultdict(int)
    digits = str(r)
    dp[len(digits)] = 1
    for i in range(len(digits) - 1, -1, -1):
        for d in range(int(digits[i]), -1, -1):
            for j in range(i + 1):
                for digit in range(10):
                    if (d == 0 and digit == 0) or (d > 0 and digit == 0):
                        dp[i] += dp[j]
                    else:
                        dp[i] += dp[j] * (d == digit)
    return sum(dp[i] for i in range(len(digits))) - sum(dp[i] for i in range(len(str(l - 1))))
