        seen = set()
        runs = 0  # number of consecutive-value blocks among distinct seen values

        for right in range(left, len(nums)):
            x = nums[right]

            if x not in seen:
                if x - 1 not in seen:
                    runs += 1
                if x + 1 in seen:
                    runs += 1
                seen.add(x)

            if x - 1 not in seen:
                runs -= 1

            total += runs - 1

    return total
