    dp = [-1] * (1 << rows)
    dp[0] = 0

    for v in values:
        ndp = dp[:]  # skip this value
        for mask, cur in enumerate(dp):
            if cur < 0:
                continue
            for r in rows_with_value[v]:
                bit = bits[r]
                if mask & bit:
                    continue
                nmask = mask | bit
                cand = cur + v
                if cand > ndp[nmask]:
                    ndp[nmask] = cand
        dp = ndp

    return max(dp)
