def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    _INV2 = (MOD + 1) // 2
    dp = [0] * (k + 1)
    dp[0] = 1
    for x in nums:
        if x > k:
            continue
        for s in range(k - x, -1, -1):
            v = dp[s]
            if v:
                dp[s + x] = (dp[s + x] + v * _INV2) % MOD
    return dp[k] * pow(2, len(nums), MOD) % MOD
