def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    if s == t:
        return True
    if x + y > n:
        return False
    if s.count('1') != t.count('1'):
        return False
    zero_positions_s = [i for i, c in enumerate(s) if c == '0']
    zero_positions_t = [i for i, c in enumerate(t) if c == '0']
    one_positions_s = [i for i, c in enumerate(s) if c == '1']
    one_positions_t = [i for i, c in enumerate(t) if c == '1']
    for i in range(len(zero_positions_s)):
        if (zero_positions_s[i] - zero_positions_t[i]) % y != 0:
            return False
    for i in range(len(one_positions_s)):
        if (one_positions_s[i] - one_positions_t[i]) % x != 0:
            return False
    return True
