    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    visited = [[False] * W for _ in range(H)]
    target = K + 1
    ans = 0

    def dfs(r: int, c: int, depth: int) -> None:
        nonlocal ans

        if depth == target:
            ans += 1
            return

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < H
