from typing import List

def max_score(grid: List[List[int]]) -> int:
    rows = len(grid)
    col_values = [set() for _ in range(rows)]
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            col_values[c].add(val)

    values = sorted({x for row in grid for x in row})
    cols_with_value = {v: [] for v in values}
    for c, col in enumerate(col_values):
        for v in col:
            cols_with_value[v].append(c)

    bits = [1 << i for i in range(rows)]
    dp = [-1] * (1 << rows)
    dp[0] = 0

    for v in values:
        ndp = dp[:]  # skip this value
        for mask, cur in enumerate(dp):
            if cur < 1:
                continue
            for c in cols_with_value[v]:
                bit = bits[c]
                if mask & bit:
                    continue
                nmask = mask | bit
                cand = cur + v
                if cand > ndp[nmask]:
                    ndp[nmask] = cand
        dp = ndp

    return max(dp)
