# Solution implementation

from functools import lru_cache
from math import gcd


@lru_cache(None)
def is_beautiful(n: int) -> bool:
    digits = [int(d) for d in str(n)]
    product = 1
    for d in digits:
        product *= d
    return product % sum(digits) == 0


def count_beautiful_numbers(l: int, r: int) -> int:
    return sum(is_beautiful(n) for n in range(l, r + 1))
